import{t as e}from"./utils-COoNfFoj.js";var t={slug:`soli-cayetano`,influencerName:`Soli Cayetano`,influencerHandle:`@lattes.and.leases`,influencerAvatarUrl:`${e}/soli-cayetano-avatar.png`,heroDescription:`Picking a new market to invest in used to take my team weeks of research. Perplexity computer built me a comprehensive market dashboard using this prompt — all while I drank my morning latte. Use my prompt or create your own!`,assetTitle:`The 25 Best US Hotel Markets`,screenshotUrl:`${e}/soli-cayetano.png`,remixUrl:`https://www.perplexity.ai/computer/a/boutique-hotel-investment-dash-GpxVCwbaQBeI3LVsaKkpmg`,promptTitle:`Try Soli's prompt`,promptText:`Build an interactive map-based dashboard ranking the 25 best US markets for boutique luxury hotel investment, targeting cities with strong nightlife, dining, and weekend-getaway appeal for 30s-40s travelers. Score each market 0-100 across luxury ADR (20), airport access (15), ease of entry — cost, entitlements, trophy-brand competition, housing rules (15), RevPAR (12), nightlife (10), labor pool (10), 50-mile population (8), RevPAR forecast (5), STR regulation (5), with a saturation penalty up to −15. Use hotel-only sources (STR, CoStar, HVS, DMOs), cite everything, tier results A through D, and include photos and a detail panel per market.`};export{t as default};
